-- Lote 07 do catálogo de talentos SRD. Tradução; sem alteração de engine_status.
begin;
update public.srd_feats set nome_pt='Encontrão Aprimorado', descricao_pt='Pré-requisitos: Força 13, Ataque Poderoso. Benefício: Quando você realiza um encontrão, não provoca um ataque de oportunidade do defensor. Além disso, recebe +4 de bônus no teste resistido de Força realizado para empurrar o defensor. Especial: Um guerreiro pode escolher Encontrão Aprimorado como um de seus talentos adicionais de guerreiro.' where id='srd35_feat_improved_bull_rush';
update public.srd_feats set nome_pt='Contramágica Aprimorada', descricao_pt='Benefício: Ao realizar uma contramágica, você pode usar uma magia da mesma escola que seja de um ou mais níveis acima da magia-alvo. Normal: Sem este talento, você só pode neutralizar uma magia usando a mesma magia ou uma magia especificamente designada para neutralizar a magia-alvo.' where id='srd35_feat_improved_counterspell';
update public.srd_feats set nome_pt='Sucesso Decisivo Aprimorado', descricao_pt='Escolha um tipo de arma. Pré-requisitos: Proficiência com a arma escolhida, bônus base de ataque +8. Benefício: Ao usar a arma escolhida, sua margem de ameaça de acerto decisivo é dobrada. Especial: Você pode escolher este talento várias vezes. Seus efeitos não se acumulam. Cada vez que o escolher, ele se aplica a um novo tipo de arma. Este efeito não se acumula com nenhum outro efeito que amplie a margem de ameaça de uma arma. Um guerreiro pode escolher Sucesso Decisivo Aprimorado como um de seus talentos adicionais de guerreiro.' where id='srd35_feat_improved_critical';
update public.srd_feats set nome_pt='Desarmar Aprimorado', descricao_pt='Pré-requisitos: Inteligência 13, Especialização em Combate. Benefício: Você não provoca um ataque de oportunidade ao tentar desarmar um oponente, e o oponente também não tem a oportunidade de desarmá-lo. Além disso, recebe +4 de bônus na jogada de ataque resistida realizada para desarmar o oponente. Normal: Consulte as regras normais de desarmar. Especial: Um guerreiro pode escolher Desarmar Aprimorado como um de seus talentos adicionais de guerreiro. Um monge pode escolhê-lo como talento adicional no 6º nível, mesmo que não cumpra os pré-requisitos.' where id='srd35_feat_improved_disarm';
commit;